import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.BQ1gajhD.js";const f=JSON.parse('{"title":"北京合生汇","description":"","frontmatter":{},"headers":[],"relativePath":"landmarks/heshenghui.md","filePath":"landmarks/heshenghui.md","lastUpdated":1787033866000}'),n={name:"landmarks/heshenghui.md"};function d(s,t,o,i,h,g){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="北京合生汇" tabindex="-1">北京合生汇 <a class="header-anchor" href="#北京合生汇" aria-label="Permalink to &quot;北京合生汇&quot;">​</a></h1><p><img src="https://images.unsplash.com/photo-1441986300917-64674bd600d8?w=1200" alt="北京合生汇"></p><blockquote><p>&quot;CBD东南的夜生活新坐标。&quot;</p></blockquote><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>北京合生汇位于朝阳区西大望路，紧邻CBD商务区，是一座集购物、餐饮、娱乐于一体的大型商业综合体。它地处九龙山商圈，交通便利，业态丰富，尤其以 B1 层的&quot;21街区&quot;美食空间和丰富的夜宵选择著称，是年轻人聚会、逛街、觅食的热门去处，也是北京商圈夜经济的新地标。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">项目</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>开放时间</strong></td><td style="text-align:left;">10:00-22:00（部分餐饮延长）</td></tr><tr><td style="text-align:left;"><strong>门票价格</strong></td><td style="text-align:left;">免费</td></tr><tr><td style="text-align:left;"><strong>建议游玩</strong></td><td style="text-align:left;">2-4小时</td></tr><tr><td style="text-align:left;"><strong>最佳季节</strong></td><td style="text-align:left;">四季皆宜，夜晚最佳</td></tr><tr><td style="text-align:left;"><strong>交通方式</strong></td><td style="text-align:left;">地铁7号线/14号线九龙山站</td></tr><tr><td style="text-align:left;"><strong>地址</strong></td><td style="text-align:left;">北京市朝阳区西大望路21号</td></tr></tbody></table><h2 id="商业特色" tabindex="-1">商业特色 <a class="header-anchor" href="#商业特色" aria-label="Permalink to &quot;商业特色&quot;">​</a></h2><h3 id="_21街区美食空间" tabindex="-1">21街区美食空间 <a class="header-anchor" href="#_21街区美食空间" aria-label="Permalink to &quot;21街区美食空间&quot;">​</a></h3><p>合生汇 B1 层与 B2 层被打造成沉浸式美食街区，汇集数百家餐饮品牌与网红小吃，是美食爱好者的天堂。</p><h3 id="时尚购物" tabindex="-1">时尚购物 <a class="header-anchor" href="#时尚购物" aria-label="Permalink to &quot;时尚购物&quot;">​</a></h3><p>商场涵盖国际快时尚、设计师品牌、运动潮流等丰富品类，购物选择多样。</p><h3 id="娱乐休闲" tabindex="-1">娱乐休闲 <a class="header-anchor" href="#娱乐休闲" aria-label="Permalink to &quot;娱乐休闲&quot;">​</a></h3><p>影院、KTV、运动体验馆等休闲业态齐全，适合家庭与朋友聚会。</p><h2 id="游览攻略" tabindex="-1">游览攻略 <a class="header-anchor" href="#游览攻略" aria-label="Permalink to &quot;游览攻略&quot;">​</a></h2><h3 id="推荐路线" tabindex="-1">推荐路线 <a class="header-anchor" href="#推荐路线" aria-label="Permalink to &quot;推荐路线&quot;">​</a></h3><p><strong>半日路线</strong>：</p><p>九龙山站 → B1/B2美食街区 → 楼层购物 → 影院或娱乐体验 → 晚餐</p><h3 id="实用贴士" tabindex="-1">实用贴士 <a class="header-anchor" href="#实用贴士" aria-label="Permalink to &quot;实用贴士&quot;">​</a></h3><ol><li><strong>交通</strong>：地铁7号线/14号线九龙山站直达</li><li><strong>错峰</strong>：周末人流较大，工作日晚上相对清闲</li><li><strong>餐饮</strong>：21街区性价比高、选择多，夜宵时段也很热闹</li><li><strong>搭配</strong>：与国贸CBD、蓝色港湾等商圈联动游玩</li></ol><h3 id="交通方式" tabindex="-1">交通方式 <a class="header-anchor" href="#交通方式" aria-label="Permalink to &quot;交通方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">方式</th><th style="text-align:left;">路线</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>地铁</strong></td><td style="text-align:left;">7号线/14号线九龙山站</td></tr><tr><td style="text-align:left;"><strong>公交</strong></td><td style="text-align:left;">西大望路沿线多路公交</td></tr><tr><td style="text-align:left;"><strong>打车</strong></td><td style="text-align:left;">定位&quot;北京合生汇&quot;即可</td></tr></tbody></table><h2 id="周边景点" tabindex="-1">周边景点 <a class="header-anchor" href="#周边景点" aria-label="Permalink to &quot;周边景点&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">景点</th><th style="text-align:center;">距离</th><th style="text-align:left;">特色</th></tr></thead><tbody><tr><td style="text-align:left;">国贸CBD</td><td style="text-align:center;">车程10分钟</td><td style="text-align:left;">摩天楼夜景</td></tr><tr><td style="text-align:left;">北京SKP</td><td style="text-align:center;">车程10分钟</td><td style="text-align:left;">高端购物中心</td></tr><tr><td style="text-align:left;">朝阳公园</td><td style="text-align:center;">车程15分钟</td><td style="text-align:left;">城市公园</td></tr><tr><td style="text-align:left;">蓝色港湾</td><td style="text-align:center;">车程15分钟</td><td style="text-align:left;">欧式风情商圈</td></tr></tbody></table><h2 id="文化意义" tabindex="-1">文化意义 <a class="header-anchor" href="#文化意义" aria-label="Permalink to &quot;文化意义&quot;">​</a></h2><p>北京合生汇是北京商业综合体升级的缩影，从单纯的购物场所转型为集美食、娱乐、社交于一体的生活空间，反映了新一代消费者对&quot;一站式体验&quot;的需求。</p><hr><p><strong>📍 地址</strong>：北京市朝阳区西大望路21号 <strong>🚇 地铁</strong>：7号线/14号线九龙山站</p><p><strong>💡 Tips</strong>：合生汇的21街区是京城有名的美食聚集地，逛累了直接下楼就能吃饱。</p>',29)])])}const c=e(n,[["render",d]]);export{f as __pageData,c as default};
